def normalized_text(value: str) -> str:
    return value.strip().lower()

result = normalized_text("  Refund Request ")
print(result)

from dataclasses import dataclass

@dataclass(frozen=True)
class Ticket:
    ticket_id: str
    text: str


def ticket_length(ticket: Ticket) -> int:
    return len(ticket.text)

item = Ticket(ticket_id="T-104", text="Cannot sign in")
print(ticket_length(item))

def parse_limit(raw: str) -> int:
    try:
        limit = int(raw)
    except ValueError as exc:
        raise ValueError("limit must be an integer") from exc

    if limit < 1:
        raise ValueError("limit must be positive")
    return limit


print(parse_limit("12"))
try:
    parse_limit("abc")
except ValueError as exc:
    print(type(exc).__name__, str(exc))
